const f=$input.first().json;
let identifiers;
try { identifiers=JSON.parse(f.identifiers_json); } catch { throw new Error('identifiers_json: нужен JSON-массив кадастровых номеров или lot_key.'); }
const pattern=/^(?:[0-9]{1,30}:[0-9]{1,10}|[0-9]{2}:[0-9]{2}:[0-9]{1,12}:[0-9]{1,12})$/;
if(!Array.isArray(identifiers)||identifiers.length<1||identifiers.length>50||identifiers.some(x=>typeof x!=='string'||!pattern.test(x)))throw new Error('Передайте от 1 до 50 точных идентификаторов; адреса и SQL недопустимы.');
identifiers=[...new Set(identifiers)];
for(const k of ['destination_latitude','destination_longitude'])if(typeof f[k]!=='number'||!Number.isFinite(f[k])||Math.abs(f[k])>(k.endsWith('latitude')?90:180))throw new Error('Нужны проверенные числовые координаты конечной точки.');
if(f.destination_latitude===0&&f.destination_longitude===0)throw new Error('Нулевая конечная точка недопустима.');
if(typeof f.destination_label!=='string'||!f.destination_label.trim()||f.destination_label.length>200||/[\x00-\x1f]/.test(f.destination_label))throw new Error('Нужно название подтверждённой конечной точки.');
return [{json:{identifiers,identifiers_json:JSON.stringify(identifiers),destination_latitude:f.destination_latitude,destination_longitude:f.destination_longitude,destination_label:f.destination_label.trim()}}];

const input=$('Validate Batch Input').first().json;
const rows=$input.all().map(x=>x.json).filter(x=>x.lot_key);
if(rows.length>=1001)throw new Error('Слишком много совпадений. Уточните точные lot_key.');
return input.identifiers.map(identifier=>{
 const matches=rows.filter(x=>x.lot_key===identifier||x.cadastral_number===identifier);
 const base={identifier,destination_latitude:input.destination_latitude,destination_longitude:input.destination_longitude,destination_label:input.destination_label};
 if(matches.length!==1)return {json:{...base,valid:false,error_code:matches.length?'AmbiguousLot':'LotNotFound',matches:matches.map(x=>({lot_key:x.lot_key,cadastral_number:x.cadastral_number}))}};
 const row=matches[0],lat=Number(row.latitude),lon=Number(row.longitude);
 const record={...base,lot_key:row.lot_key,cadastral_number:row.cadastral_number,address:row.address,source_url:row.source_url,last_seen_at:row.last_seen_at};
 if(row.latitude==null||row.longitude==null||row.latitude===''||row.longitude===''||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||(lat===0&&lon===0))return {json:{...record,valid:false,error_code:'InvalidLotCoordinates'}};
 return {json:{...record,valid:true,origin_latitude:lat,origin_longitude:lon,origin_label:String(row.cadastral_number||row.lot_key)}};
});

const request=$('Loop Routes').item.json;
const result=$input.first().json;
const base={identifier:request.identifier,lot_key:request.lot_key,cadastral_number:request.cadastral_number,address:request.address,source_url:request.source_url};
if(result.ok!==true)return [{json:{...base,ok:false,error_code:result.error_code||'RoutingServiceError',message:result.message||'Не удалось рассчитать маршрут. Расстояние не подтверждено.'}}];
return [{json:{...base,ok:true,distance_m:result.distance_m,duration_s:result.duration_s,distance_km_rounded:result.distance_km_rounded,duration_text:result.duration_text,origin_road_offset_m:result.snapped_points?.find(x=>x.point==='origin')?.offset_m,destination_road_offset_m:result.snapped_points?.find(x=>x.point==='destination')?.offset_m,map_data_timestamp:result.map_data_timestamp}}];

const input=$('Validate Batch Input').first().json;
const results=$input.all().map(x=>x.json);
if(results.length!==input.identifiers.length||new Set(results.map(x=>x.identifier)).size!==input.identifiers.length)throw new Error('Пакетный расчёт вернул неполный или повторный набор результатов.');
const routes=results.filter(x=>x.ok===true).sort((a,b)=>a.duration_s-b.duration_s||a.distance_m-b.distance_m||a.identifier.localeCompare(b.identifier));
const failures=results.filter(x=>x.ok!==true);
return [{json:{ok:failures.length===0,partial:routes.length>0&&failures.length>0,requested_count:input.identifiers.length,calculated_count:routes.length,failed_count:failures.length,destination:{label:input.destination_label,latitude:input.destination_latitude,longitude:input.destination_longitude},sorted_by:'duration_s_ascending',routes,failures,provider:'OSRM / OpenStreetMap',traffic_included:false,checked_at_utc:new Date().toISOString(),warnings:['Координаты начала — центры участков из базы; подъезд и законность доступа отдельно не проверены.','Время приблизительное, без текущих пробок и перекрытий.','Если смещение любой точки к дороге больше 100 м, укажите это для соответствующего маршрута.','Это сравнение только переданного списка, не всех участков базы.']}}];
